  bev(`BASE_ITEMS.length=0; DATA.items.forEach(function(i){ BASE_ITEMS.push(i); BASE_ASK[i.id]=i.ask.slice(); }); applyState(S); MS.years[MS.cur]=S; save(); 'ok'`);
  const cur = +bev('MS.cur'), Y = [cur, cur + 1, cur + 2], fyl = y => 'FY' + (y % 100);
