  const q = [], r = []; W.forEach(x => { const p = t * x; let d = p / s, m = p - d * s; if (m < 0n) { d -= 1n; m += s; } q.push(d); r.push(m); });
  let left = t - q.reduce((a, b) => a + b, 0n);
