      const ok = click(X, 'flowOneYear(2026)'), b0 = now(X), okOff = click(X, 'flowSetPseudo("on",false)'), b1 = now(X);
      const R = reopen(X), r = now(R), P = panel(R), B = await book(R), okOn = click(R, 'flowSetPseudo("on",true)'), r2 = now(R);
